        if _text(_value(record, "ACCT_TYP")) not in ("C", "P", "R", "X"):
            _add_error(errors, "E1002", "Invalid account type")

    # ACC-003
    if event in ("INSERT", "UPDATE"):
        if _number(_value(record, "ANN_REV")) < Decimal(0):
            _add_error(errors, "E1003", "Annual revenue negative")

    # ACC-004
