        old_on_hold = _text(_value(previous, "CRED_HOLD")) == "Y"
        new_released = _text(_value(record, "CRED_HOLD")) == "N"
        zero_or_less_limit = _number(_value(record, "CRED_LIMIT")) <= Decimal(0)
        if old_on_hold and new_released and zero_or_less_limit:
            _add_error(
                errors,
                "E1004",
                "Cannot release credit hold with zero credit limit",
            )

    # ACC-005
    if event in ("INSERT", "UPDATE"):
        if len(_text(_value(record, "REGION_CD"))) != 3:
            _add_error(
                errors,
                "E1005",
                "Region code must be 3 chars",
                "WARN",
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
